mapper.select:
select target_id as hostId, count(*) as times from situation_attack_message_history
(defense_type is null or defense_level is null or defense_level != 3) and attack_or_defense = 'attack' and is_history = 0
and scene_id = #{sceneId}
and type in
#{attackType}
group by target_id order by times desc

select top 1 create_time from situation_attack_message_history
scene_id = #{sceneId}
order by create_time

select *
from situation_attack_message_history


        scene_id = #{sceneId}


        and create_time > #{startTime}


        and create_time < #{endTime}


order by create_time

select create_time as time, defense_target_id as hostId, defense_type from situation_attack_message_history
attack_or_defense = 'defense' and defense_type is not null
and scene_id = #{sceneId}

select * from situation_attack_message_history
defense_level = 3 and attack_or_defense = 'defense'
and defense_target_id = #{defenseTargetId}
